.gzp-escritorio{
          antecedentes:
            gradiente radial (120% 70% al 50% 0%, rgba(214,178,110,.05), transparente 58%),
            gradiente radial (130% 100% al 50% 108%, rgba(0,0,0,.34), transparente 62%),
            /* veta de la madera: espaciada amplia e irregularmente (rayas viejas
               Parecía terciopelo) */
            gradiente-lineal-repetitivo (92 grados,
              rgba(0,0,0,.13) 0 3px,
              transparente 3px 17px,
              rgba(255,255,255,.016) 17px 20px,
              transparente 20px 41px,
              rgba(0,0,0,.09) 41px 43px,
              transparente 43px 74px),
            /*juntas de los tableros*/
            gradiente-lineal-repetitivo (90 grados,
              rgba(0,0,0,.42) 0 2px,
              transparente 2px 148px),
